  func TestRehearsal_DetectsLockAcrossWaitOrder(t *testing.T) {
      t.Skip("guard test: enable to verify the regression test catches lock-across-wait")

      var (
          mu    sync.Mutex
          wg    sync.WaitGroup
          queue = make(chan int, 16)
      )
      wg.Add(8)

      mu.Lock()                                // broken: held across wg.Wait
      go func() {
          for i := 0; i < totalManifests; i++ {
              queue <- i
          }
          close(queue)
      }()

      for i := 0; i < workerCount; i++ {
          go func() {
              for range queue {
                  mu.Lock()
                  mu.Unlock()
                  wg.Done()
              }
          }()
      }

      ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
      defer cancel()
      done := make(chan struct{})
      go func() { wg.Wait(); close(done) }()

      select {
      case <-done:
          t.Fatal("expected deadlock but wg.Wait returned")
      case <-ctx.Done():
          // expected: deadline fires, lock-across-wait detected
      }
  }

Bug confirmed. The refactor's date truncation drops the 45-minute component, so the 24h-join check sees 24h 00m instead of 24h 45m and lets the pair collapse. That violates the 2025-03-27 lock (24h rule on joined cards; >24h must stay separate with source ts).

Fix direction: compute the spread on full source timestamps (display-tz or UTC, just not date-truncated). Truncation is fine for display grouping, but the join eligibility check has to see hour/minute precision. A regression fixture with a pair at 24h+1m (negative case) would have caught this.

